DO $$ DECLARE definition text; fixed text; BEGIN SELECT pg_get_functiondef('public.quality_checked_command(jsonb)'::regprocedure) INTO definition; fixed:=replace(definition,'FROM jsonb_array_elements(sv.payload->''questions'') q WHERE q->>''id''=a','FROM jsonb_array_elements(sv.payload->''questions'') question_entry WHERE question_entry->>''id''=a'); IF fixed=definition THEN RAISE EXCEPTION 'Expected validation expression was not found';END IF;EXECUTE fixed;END $$;